const UNITS = { h: 3600, m: 60, s: 1 };

exports.parseDuration = (str) => {
  let total = 0;
  for (const [, num, unit] of str.matchAll(/(\d+)([hms])/g)) {
    total = Number(num) * UNITS[unit];
  }
  return total;
};
